/* Original Northstar grammar lessons, organised by CEFR-oriented stage.
   Explanations are bilingual so learners can compare the rule and examples. */
(() => {
  const lesson = (id, title, type, desc, en, hi, practice) => ({
    id, title, type, time: '12 min', desc,
    notes: [{en, hi}], practice
  });
  window.NORTHSTAR_ENGLISH_GRAMMAR = {
    Basic: {
      subtitle: 'A1–A2 · build clear everyday sentences',
      lessons: [
        lesson('g-basic-word-order','Sentence structure: subject, verb and object','GRAMMAR','Build statements, questions and short answers in a natural order.',
          'A clause needs a subject and a verb. The most common English statement order is subject + verb + object/complement: “Maya reads novels”; “Maya is happy.” Put place and time information after the main idea in a neutral sentence: “We met at the library yesterday.” English normally keeps the subject even when it is obvious: say “It is raining”, not just “Is raining.” Questions change the order; see the question lesson.',
          'Clause यानी वाक्यांश में subject और verb ज़रूरी होते हैं। सामान्य क्रम Subject + Verb + Object/पूरक है: “Maya reads novels” (माया उपन्यास पढ़ती है); “Maya is happy” (माया खुश है)। जगह और समय अक्सर मुख्य बात के बाद आते हैं: “We met at the library yesterday.” अंग्रेज़ी में subject सामान्यतः छोड़ा नहीं जाता; “It is raining” कहें, केवल “Is raining” नहीं। प्रश्नों में क्रम बदलता है—वह आगे अलग topic है।',
          'Introduce yourself and say what you do, where you do it and when.'),
        lesson('g-basic-be-have-do','Be, do and have: the core helper verbs','GRAMMAR','Use the three most common English verbs as main verbs and auxiliaries.',
          'BE forms are am/is/are (present) and was/were (past): “I am ready; they were late.” DO forms are do/does/did; they help form questions and negatives (“Does she work?” “We did not go”) and can add emphasis (“I do understand”). HAVE forms are have/has/had; they show possession (“She has a car”) and build perfect tenses (“She has finished”). Match present forms to the subject: I am/have/do; he or she is/has/does; you/we/they are/have/do.',
          'BE के रूप am/is/are (वर्तमान) और was/were (भूतकाल) हैं: “I am ready”; “They were late.” DO के रूप do/does/did प्रश्न और नकार बनाते हैं: “Does she work?” “We did not go”; जोर देने में भी आते हैं: “I do understand.” HAVE के रूप have/has/had अधिकार बताते हैं (“She has a car”) और perfect tense बनाते हैं (“She has finished”)। Subject के अनुसार रूप चुनें: I am/have/do; he/she is/has/does; you/we/they are/have/do।',
          'Make one present statement, one negative and one question with be, do and have.'),
        lesson('g-basic-pronouns','Subject, object and possessive pronouns','GRAMMAR','Choose pronouns by their job in a sentence.',
          'Subject pronouns do the action: I, you, he, she, it, we, they. Object pronouns receive an action or follow a preposition: me, you, him, her, it, us, them (“Call me”; “with them”). Possessive determiners come before a noun: my, your, his, her, its, our, their (“their house”). Possessive pronouns stand alone: mine, yours, his, hers, ours, theirs (“The blue bag is mine”). Use reflexives only when subject and object are the same or for emphasis: “She introduced herself”; “I made it myself.”',
          'Subject pronoun काम करता है: I, you, he, she, it, we, they। Object pronoun पर काम होता है या preposition के बाद आता है: me, you, him, her, it, us, them (“Call me”; “with them”)। Possessive determiner noun से पहले आता है: my, your, his, her, its, our, their (“their house”)। Possessive pronoun अकेला खड़ा होता है: mine, yours, his, hers, ours, theirs (“The blue bag is mine”)। Reflexive रूप तभी लगाएँ जब subject और object एक ही हों (“She introduced herself”) या जोर देना हो (“I made it myself”)।',
          'Describe a friend using a subject pronoun, an object pronoun and a possessive form.'),
        lesson('g-basic-nouns','Nouns: plurals, countable and uncountable','GRAMMAR','Talk about people and things, and choose the right quantity words.',
          'Most countable nouns form the plural with -s (“book/books”); add -es after s, sh, ch, x or z (“box/boxes”), and change consonant + y to -ies (“city/cities”). Some plurals are irregular (“child/children”, “person/people”). Countable nouns have singular/plural forms and can follow a/an or numbers. Uncountable nouns such as information, advice, furniture and water normally have no plural and do not take a/an; say “some advice” or “a piece of advice.”',
          'अधिकतर countable nouns में plural के लिए -s जोड़ें (“book/books”); s, sh, ch, x, z के बाद -es (“box/boxes”); consonant + y में y बदलकर -ies (“city/cities”)। कुछ plural अनियमित हैं (“child/children”, “person/people”)। Countable noun के singular/plural रूप होते हैं और उसके साथ a/an या संख्या आ सकती है। information, advice, furniture, water जैसे uncountable nouns सामान्यतः plural नहीं लेते और इनके पहले a/an नहीं आता; “some advice” या “a piece of advice” कहें।',
          'Name three things you own; include one plural noun and one uncountable noun.'),
        lesson('g-basic-articles','A, an, the and zero article','GRAMMAR','Choose articles for new, known and general nouns.',
          'Use a/an with one nonspecific countable singular noun: a before a consonant sound (“a university”), an before a vowel sound (“an hour”). Use the when the listener can identify the thing, when it was already mentioned, or for unique things: “I saw a dog. The dog was wet”; “the sun.” Use no article for plural or uncountable nouns in general statements: “Dogs need exercise”; “Music helps me focus.” The choice depends on meaning and sound, not just spelling.',
          'एक अनिश्चित singular countable noun के साथ a/an लगाएँ: consonant sound से पहले a (“a university”), vowel sound से पहले an (“an hour”)। जब सुनने वाला वस्तु पहचान सकता हो, उसका पहले उल्लेख हुआ हो, या वह अद्वितीय हो, तब the लगाएँ: “I saw a dog. The dog was wet”; “the sun.” सामान्य अर्थ में plural या uncountable noun के साथ article न लगाएँ: “Dogs need exercise”; “Music helps me focus.” चुनाव अर्थ और उच्चारण की ध्वनि पर निर्भर है, केवल spelling पर नहीं।',
          'Describe a room using a/an for a new item and the when you mention it again.'),
        lesson('g-basic-determiners','This/that, some/any, much/many and possessives','GRAMMAR','Point to things and talk about quantity.',
          'This/these refer to things near the speaker; that/those refer to things farther away (“this chair”, “those houses”). Use some mainly in affirmative offers/statements and any mainly in negatives/questions (“some tea”; “any questions?”; “I do not have any”). Use many/few with plural countable nouns (“many books”, “few chairs”) and much/little with uncountable nouns (“much time”, “little water”); a lot of works with both. Possessive determiners my/your/his/her/its/our/their come before a noun.',
          'This/these पास की वस्तु और that/those दूर की वस्तु बताते हैं (“this chair”, “those houses”)। Some सामान्यतः affirmative कथन/offer में और any प्रश्न/नकार में आता है (“some tea”; “any questions?”; “I do not have any”)। Many/few plural countable noun के साथ (“many books”); much/little uncountable noun के साथ (“much time”)। A lot of दोनों के साथ चल सकता है। My/your/his/her/its/our/their noun से ठीक पहले आते हैं।',
          'Ask a friend what they have at home; use some, any, many and much.'),
        lesson('g-basic-present-simple','Present simple: habits, facts and schedules','GRAMMAR','Speak about routines and things that are generally true.',
          'Use the base verb for I/you/we/they and add -s/-es for he/she/it: “I cook”; “She watches.” Add -es after -s, -sh, -ch, -x, -o; consonant + y changes to -ies (“study/studies”). Make negatives with do not/does not + base verb (“He does not drive”); questions use do/does + subject + base verb (“Does he drive?”). Frequency adverbs usually go before a main verb (“I often walk”) but after be (“She is usually kind”). Use it for habits, facts and regular schedules.',
          'I/you/we/they के साथ base verb और he/she/it के साथ -s/-es लगाएँ: “I cook”; “She watches.” -s, -sh, -ch, -x, -o के बाद -es; consonant + y में -ies (“study/studies”)। नकार: do not/does not + base verb (“He does not drive”); प्रश्न: do/does + subject + base verb (“Does he drive?”)। Frequency adverb main verb से पहले (“I often walk”), लेकिन be के बाद (“She is usually kind”) आता है। आदत, तथ्य और नियमित समय-सारणी के लिए इसका प्रयोग करें।',
          'Describe your weekday routine with three frequency adverbs.'),
        lesson('g-basic-present-continuous','Present continuous: actions now and temporary situations','GRAMMAR','Form be + verb-ing and contrast it with routines.',
          'Form it with am/is/are + verb-ing: “I am speaking”; “They are waiting.” Use it for an action happening now, a temporary situation around now, or a planned near-future arrangement (“I am meeting Ana at six”). For spelling, usually add -ing; drop silent e (“make/making”); double a final consonant in a stressed consonant-vowel-consonant pattern (“sit/sitting”). State verbs such as know, own and believe are not normally continuous when they describe a state. Contrast: “I work here” (regular fact) vs “I am working from home this week” (temporary).',
          'am/is/are + verb-ing से बनाएँ: “I am speaking”; “They are waiting.” अभी चल रही क्रिया, अस्थायी स्थिति, या पक्की निकट भविष्य की व्यवस्था के लिए प्रयोग करें (“I am meeting Ana at six”)। सामान्यतः -ing जोड़ें; silent e हटाएँ (“make/making”); छोटे stressed consonant-vowel-consonant शब्द में अंतिम consonant दोहराएँ (“sit/sitting”)। know, own, believe जैसे state verbs अवस्था बताने पर सामान्यतः continuous नहीं होते। अंतर: “I work here” नियमित तथ्य; “I am working from home this week” अस्थायी स्थिति।',
          'Say what you are doing now and what temporary change you have this week.'),
        lesson('g-basic-past-simple','Past simple: finished events and irregular verbs','GRAMMAR','Tell someone what happened at a finished time.',
          'Use the past form for a completed past event, often with yesterday, last week or in 2020. Regular verbs add -ed; spelling changes include consonant + y → -ied (“try/tried”) and final silent e + d (“live/lived”). Many common verbs are irregular (“go/went”, “see/saw”, “make/made”) and must be learned. Negatives use did not + base verb (“did not go”); questions use did + subject + base verb (“Did you go?”). Be uses was/were and does not use did in questions (“Were you ready?”).',
          'बीते हुए समय में पूरी हो चुकी घटना के लिए past form लगाएँ; साथ में yesterday, last week, in 2020 आ सकते हैं। Regular verb में -ed; consonant + y बदलकर -ied (“try/tried”), silent e के बाद केवल d (“live/lived”)। कई आम verbs अनियमित हैं (“go/went”, “see/saw”, “make/made”)। नकार: did not + base verb (“did not go”); प्रश्न: did + subject + base verb (“Did you go?”)। Be के लिए was/were आता है और did नहीं (“Were you ready?”)।',
          'Tell a short story about yesterday using two regular and two irregular past verbs.'),
        lesson('g-basic-future-forms','Talking about the future: will, going to and present continuous','GRAMMAR','Choose a future form based on your meaning.',
          'Use will + base verb for a decision made while speaking, an offer/promise, or a prediction/opinion (“I will help”; “I think it will rain”). Use be going to + base verb for an existing intention or evidence-based prediction (“I am going to apply”; “Look at those clouds!”). Use present continuous for a personal arrangement already made (“We are having lunch with Priya tomorrow”). Use present simple for timetables (“The train leaves at 8”). These forms overlap; context signals the intended meaning.',
          'बात करते समय लिया निर्णय, offer/promise या अपनी राय पर आधारित अनुमान के लिए will + base verb (“I will help”; “I think it will rain”)। पहले से बना इरादा या दिख रहे प्रमाण पर अनुमान बताने के लिए be going to + base verb (“I am going to apply”)। तय व्यक्तिगत arrangement के लिए present continuous (“We are having lunch tomorrow”)। timetable के लिए present simple (“The train leaves at 8”)। इनके अर्थ कुछ जगह overlap करते हैं; संदर्भ से आशय स्पष्ट होता है।',
          'Make one spontaneous offer, one plan, one fixed arrangement and one timetable statement.'),
        lesson('g-basic-questions-negatives','Questions, negatives and short answers','GRAMMAR','Ask clear yes/no and information questions.',
          'With be, invert be and the subject: “Are you ready?” With other present/past simple verbs, add do/does/did before the subject and keep the main verb in its base form: “Does she work?” “Did they leave?” Put a question word (who, what, where, when, why, how) first when needed: “Where do you live?” Negatives use not after the auxiliary: is not, do not, did not, cannot. Short answers repeat the auxiliary (“Yes, I do”; “No, she isn’t”); do not use only yes/no in a clear response.',
          'Be के साथ be और subject उलटें: “Are you ready?” अन्य present/past simple verbs में subject से पहले do/does/did रखें और main verb base form में रहे: “Does she work?” “Did they leave?” जानकारी वाले प्रश्न में who, what, where, when, why, how पहले रखें: “Where do you live?” Auxiliary के बाद not से नकार बनाएँ: is not, do not, did not, cannot। Short answer में auxiliary दोहराएँ (“Yes, I do”; “No, she isn’t”)।',
          'Ask and answer five questions about a new friend, using short answers.'),
        lesson('g-basic-modals','Can, could, should, must and have to','GRAMMAR','Express ability, requests, advice and obligation.',
          'A modal is followed by the base verb without to: “She can swim”; “You should rest.” Can expresses present ability/permission; could often expresses past ability or a polite request (“Could you help?”). Should gives advice. Must signals strong obligation or a strong conclusion; have to expresses an external rule/necessity and changes form (“has to”, “had to”). Must not means prohibition; do not have to means there is no need—these meanings differ. Do not add -s to a modal: “He can”, not “He cans.”',
          'Modal के बाद बिना to के base verb आता है: “She can swim”; “You should rest.” Can वर्तमान क्षमता/अनुमति बताता है; could अक्सर past ability या विनम्र request है (“Could you help?”)। Should सलाह है। Must कड़ी बाध्यता या मजबूत निष्कर्ष; have to बाहरी नियम/ज़रूरत बताता है और रूप बदलता है (“has to”, “had to”)। Must not = मनाही; do not have to = ज़रूरी नहीं—दोनों अलग अर्थ हैं। Modal में -s न जोड़ें: “He can”, न कि “He cans.”',
          'Give a friend one piece of advice, one rule and one polite request.'),
        lesson('g-basic-adjectives-adverbs','Adjectives and adverbs','GRAMMAR','Describe people, things and how actions happen.',
          'Adjectives describe nouns and commonly come before them or after linking verbs: “a quiet room”; “The room is quiet.” Adverbs often describe verbs, adjectives or other adverbs: “She speaks clearly”; “really useful”; “very slowly.” Many manner adverbs use adjective + -ly (“careful/carefully”), but forms vary (“good/well”, “fast/fast”). Linking verbs such as look, feel, seem and sound usually take an adjective (“You look tired”), not an adverb. Adverbs of frequency usually precede a main verb but follow be.',
          'Adjective noun का वर्णन करता है और noun से पहले या linking verb के बाद आता है: “a quiet room”; “The room is quiet.” Adverb verb/adjective/दूसरे adverb का वर्णन करता है: “She speaks clearly”; “really useful”; “very slowly.” कई manner adverbs में adjective + -ly (“careful/carefully”), पर रूप बदलते हैं (“good/well”, “fast/fast”)। look, feel, seem, sound जैसे linking verbs के बाद सामान्यतः adjective (“You look tired”), adverb नहीं। Frequency adverb main verb से पहले, be के बाद आता है।',
          'Describe a person and explain how they speak, work or help using adjectives and adverbs.'),
        lesson('g-basic-comparatives','Comparatives and superlatives','GRAMMAR','Compare two or more people, places or choices.',
          'Use -er + than with many short adjectives (“smaller than”) and more + adjective with many longer adjectives (“more useful than”). Use the + -est or the most to identify the top degree in a group (“the tallest”, “the most interesting”). Change spelling where needed: big/bigger/biggest; happy/happier/happiest. Some forms are irregular: good/better/best; bad/worse/worst; far/farther/farthest (also further/furthest). Do not double-mark: say “more useful”, not “more useful-er.”',
          'दो चीज़ों की तुलना में छोटे adjective के साथ -er + than (“smaller than”), लंबे adjective के साथ more + adjective (“more useful than”)। समूह में सबसे अधिक गुण बताने के लिए the + -est या the most (“the tallest”, “the most interesting”)। Spelling बदल सकती है: big/bigger/biggest; happy/happier/happiest। अनियमित रूप: good/better/best; bad/worse/worst; far/farther/farthest (further/furthest भी)। दो comparative marker साथ न लगाएँ: “more useful”, “more useful-er” नहीं।',
          'Compare two cities, foods or study methods; then say which is the best for you.'),
        lesson('g-basic-prepositions','Prepositions of place, time and movement','GRAMMAR','Show where, when and in which direction something happens.',
          'Place: in for an enclosed area (“in the room”), on for a surface (“on the table”), at for a point/location (“at the station”). Time: at for clock times (“at six”), on for days/dates (“on Monday”), in for months/years/long periods (“in July”, “in 2025”). Movement: to shows a destination, into movement to the inside, from a starting point, through movement inside and out, across from one side to another. Many prepositions are fixed by usage (“good at”, “interested in”), so learn them with the word they follow.',
          'जगह: in = बंद/सीमित जगह (“in the room”), on = सतह (“on the table”), at = बिंदु/स्थान (“at the station”)। समय: at = घड़ी का समय (“at six”), on = दिन/तारीख (“on Monday”), in = महीना/साल/लंबी अवधि (“in July”, “in 2025”)। गति: to गंतव्य, into अंदर की ओर, from शुरुआत, through आर-पार/भीतर से, across एक तरफ़ से दूसरी तरफ़। कई prepositions fixed usage हैं (“good at”, “interested in”); इन्हें संबंधित शब्द के साथ सीखें।',
          'Describe how you travel from home to a place, and include one time expression.'),
        lesson('g-basic-there-quantifiers','There is/are, some/any, much/many and a few/a little','GRAMMAR','Say what exists and how much or how many there is.',
          'Use there is + singular/uncountable noun and there are + plural noun (“There is a shop”; “There are two parks”). Questions invert be (“Is there…?” “Are there…?”). Some is common in affirmative sentences; any is common in negatives and questions. Use many/a few/few with countable plurals; much/a little/little with uncountable nouns. A few/a little mean a small but useful amount; few/little without a means not enough. A lot of works with both noun types.',
          'Singular/uncountable noun के साथ there is और plural के साथ there are (“There is a shop”; “There are two parks”)। प्रश्न में be पहले करें (“Is there…?” “Are there…?”)। Affirmative में some; नकार/प्रश्न में any आम है। Many/a few/few countable plural; much/a little/little uncountable के साथ। A few/a little = थोड़ी मगर पर्याप्त मात्रा; few/little (बिना a) = बहुत कम/अपर्याप्त। A lot of दोनों प्रकार के noun के साथ चलता है।',
          'Describe your neighbourhood with there is/are and at least three quantity expressions.'),
        lesson('g-basic-imperatives-requests','Imperatives, instructions and polite requests','SPEAKING','Give directions and ask people to do things politely.',
          'Use the base verb to give a direct instruction or invitation (“Turn left”; “Come in”). Make a negative imperative with do not/don’t + base verb (“Don’t touch that”). Add please to soften an instruction. For a polite request, use can/could/would you + base verb (“Could you open the window, please?”). “Would you mind” is followed by a noun or verb-ing (“Would you mind waiting?”). Intonation and please affect how direct the request sounds.',
          'सीधा निर्देश/निमंत्रण देने के लिए base verb (“Turn left”; “Come in”)। नकारात्मक निर्देश: don’t + base verb (“Don’t touch that”)। Please जोड़कर निर्देश नरम करें। विनम्र अनुरोध: can/could/would you + base verb (“Could you open the window, please?”)। Would you mind के बाद noun या verb-ing (“Would you mind waiting?”)। आवाज़ का उतार-चढ़ाव और please अनुरोध को कितना सीधा/नरम बनाते हैं।',
          'Give a visitor directions and make two polite requests.'),
        lesson('g-basic-conjunctions','And, but, because, so and when','GRAMMAR','Join short ideas and make the relationship clear.',
          'And adds information; but shows contrast; because introduces a reason; so introduces a result; when gives a time relationship. Put a comma before a coordinating conjunction when it joins two complete clauses (“I was tired, but I finished”). Do not use because and so together for the same link in standard English (“Because it rained, we stayed in” or “It rained, so we stayed in”). A clause after because/when normally has a subject and verb.',
          'And जानकारी जोड़ता है; but विरोध; because कारण; so परिणाम; when समय-संबंध बताता है। जब conjunction दो पूर्ण clauses जोड़े, उससे पहले comma लगाया जा सकता है (“I was tired, but I finished”)। एक ही संबंध में because और so साथ न लगाएँ (“Because it rained, we stayed in” या “It rained, so we stayed in”)। Because/when के बाद सामान्यतः subject और verb वाला clause आता है।',
          'Explain why you chose a hobby using because, but, so and when.'),
        lesson('g-basic-have-got','Have and have got for possession','GRAMMAR','Talk about possessions, relationships and features.',
          'Have/has is common for possession in all varieties (“I have a bicycle”); have got/has got is especially common in spoken British English (“I have got a bicycle”). Both use have/has in present statements, but their question/negative forms differ by variety: “Have you got…?” / “I haven’t got…”; with have alone, especially American English, use do-support (“Do you have…?” / “I don’t have…”). Past possession normally uses had, not had got in formal teaching patterns. Have got here is not the present perfect of get.',
          'Possession के लिए have/has सभी varieties में आम है (“I have a bicycle”); have got/has got बोलचाल की British English में विशेष रूप से आम (“I have got a bicycle”)। दोनों present statement में have/has लेते हैं, पर प्रश्न/नकार के रूप अलग हैं: “Have you got…?”; have alone के साथ, खासकर American English में, do-support (“Do you have…?”) आता है। Past में had आम रूप है। यहाँ have got, get का present perfect नहीं है।',
          'Describe what you have and ask a friend whether they have got the same things.'),
        lesson('g-basic-ed-ing-adjectives','Adjectives ending in -ed and -ing','GRAMMAR','Say whether someone feels an emotion or something causes it.',
          'Many paired adjectives use -ed for the person’s feeling and -ing for the cause/quality: “I am bored” (my feeling); “The film is boring” (the film causes it). The same pattern appears in interested/interesting, excited/exciting and confused/confusing. The -ed form describes a state; the -ing form describes the source or effect. Not every adjective follows this pattern, so learn common pairs in context.',
          'कई जोड़ी adjective में -ed व्यक्ति की भावना और -ing कारण/गुण बताता है: “I am bored” (मेरी भावना); “The film is boring” (फ़िल्म ऊब पैदा करती है)। Interested/interesting, excited/exciting, confused/confusing भी ऐसे ही हैं। -ed अवस्था बताता है; -ing स्रोत/प्रभाव। हर adjective इस नियम पर नहीं, इसलिए आम जोड़े संदर्भ सहित सीखें।',
          'Describe something that makes you interested, excited or bored, and say how you feel.'),
        lesson('g-basic-possessive-apostrophe','Possessive ’s and plural possessives','GRAMMAR','Show who owns or is connected to something.',
          'Add ’s to a singular owner (“Maya’s phone”; “the child’s toy”). For a regular plural ending in -s, add only an apostrophe (“the teachers’ room”); for an irregular plural, add ’s (“the children’s books”). Possessive its has no apostrophe; it’s means it is or it has. A noun modifier can also show a type or purpose (“school bus”), so not every noun before another noun indicates ownership.',
          'Singular owner के साथ ’s (“Maya’s phone”; “the child’s toy”)। -s पर खत्म regular plural में केवल apostrophe (“the teachers’ room”); irregular plural में ’s (“the children’s books”)। Possessive its में apostrophe नहीं; it’s का अर्थ it is/it has। Noun + noun वस्तु का प्रकार/उद्देश्य भी बता सकता है (“school bus”), हमेशा अधिकार नहीं।',
          'Describe two things belonging to people with singular and plural names.'),
        lesson('g-basic-the-no-article','The or no article with places and general meanings','GRAMMAR','Use articles naturally with common places and general ideas.',
          'Use the when the place is a particular, identifiable one (“the bank near my home”), and often with plural country names, rivers, seas, mountain ranges and some institutions (“the Netherlands”, “the Nile”, “the United States”). Most singular country/city/lake names take no article (“India”, “Delhi”, “Lake Victoria”). School, work, home, bed, church and similar institutional nouns may take no article when used for their usual purpose (“go to school”); use the for a particular building or visit (“go to the school to meet a teacher”).',
          'पहचान योग्य खास स्थान के लिए the (“the bank near my home”)। Plural country names, नदियों, समुद्रों, पर्वत-शृंखलाओं और कुछ संस्थानों के साथ अक्सर the (“the Netherlands”, “the Nile”, “the United States”)। अधिकतर singular country/city/lake नाम बिना article (“India”, “Delhi”)। School/work/home/bed जैसी जगहें अपने सामान्य उद्देश्य में हों तो बिना article (“go to school”); खास इमारत/मुलाक़ात हो तो the (“go to the school to meet a teacher”)।',
          'Talk about your hometown using one place name without an article and one specific place with the.'),
        lesson('g-basic-infinitive-purpose','To + verb for purpose','GRAMMAR','Explain why you do something.',
          'Use to + base verb to explain the purpose of an action (“I called to ask a question”; “She went out to buy milk”). The purpose clause normally shares the main clause subject. To avoid confusing purpose with obligation, remember that have to + verb means necessity (“I have to call”), while go to + place names a destination (“I went to the shop”). In more formal style, in order to/so as to can make purpose explicit; use so that + clause when the subject changes or a modal is needed (“I wrote it down so that I would remember”).',
          'किसी काम का उद्देश्य बताने के लिए to + base verb (“I called to ask a question”; “She went out to buy milk”)। Purpose clause में सामान्यतः वही subject होता है। उद्देश्य के to को have to (ज़रूरत: “I have to call”) और go to + जगह (गंतव्य) से अलग पहचानें। Formal रूप में in order to/so as to; subject बदले या modal चाहिए तो so that + clause (“I wrote it down so that I would remember”)।',
          'Explain why you use three everyday tools or do three routine tasks.'),
        lesson('g-basic-adjective-prepositions','Adjectives followed by prepositions','GRAMMAR','Learn common adjective + preposition combinations.',
          'Some adjectives take a conventional preposition: good at, interested in, afraid of, proud of, similar to, responsible for. The choice is part of the phrase and often cannot be translated word for word. A noun or verb-ing form follows a preposition (“interested in music/learning music”), not a bare infinitive (“interested in learn”). Learn each adjective with its preposition and a short example; there can be different patterns with related meanings (“angry with someone/about a problem”).',
          'कुछ adjective के साथ प्रचलित preposition तय है: good at, interested in, afraid of, proud of, similar to, responsible for। यह phrase का हिस्सा है और शब्दशः अनुवाद नहीं होता। Preposition के बाद noun या verb-ing (“interested in music/learning music”) आता है, bare infinitive नहीं। Adjective और preposition उदाहरण सहित सीखें; अर्थ के अनुसार अलग pattern हो सकता है (“angry with someone/about a problem”)।',
          'Describe your interests and strengths using three adjective + preposition phrases.'),
        lesson('g-basic-verb-patterns','Common verbs followed by -ing or to + verb','GRAMMAR','Use the correct verb pattern after common verbs.',
          'Some verbs are followed by a gerund: enjoy doing, avoid doing, finish doing. Others take to + infinitive: want to do, decide to do, hope to do. Some take either with little change (start to rain/starting to rain); others change meaning, such as stop doing (end an activity) and stop to do (pause for a purpose). After a preposition, use -ing (“think about moving”). Learn the pattern with each verb; do not assume one rule fits all verbs.',
          'कुछ verbs के बाद gerund: enjoy doing, avoid doing, finish doing; कुछ के बाद to + infinitive: want to do, decide to do, hope to do। कुछ में दोनों रूपों का अर्थ लगभग समान; कुछ में अर्थ बदलता है: stop doing = काम बंद करना; stop to do = उद्देश्य से रुकना। Preposition के बाद -ing (“think about moving”)। हर verb के साथ उसका pattern सीखें; एक नियम सब पर लागू नहीं।',
          'Say what you enjoy doing, hope to do and stopped doing recently.')
      ]
    },
    Intermediate: {
      subtitle: 'B1–B2 · connect ideas and control time, stance and detail',
      lessons: [
        lesson('g-int-present-perfect','Present perfect and past simple','GRAMMAR','Separate life experience/current result from a finished past time.',
          'Form present perfect with have/has + past participle (“I have visited Rome”). Use it for an experience in an unfinished time, a recent event with a present result, or a situation continuing to now (“She has worked here for three years”). Do not normally use it with a finished past-time expression such as yesterday or in 2020; use past simple (“I visited Rome in 2020”). Use since + starting point and for + duration. Been to means visited and returned; gone to means the person is still there or travelling.',
          'Present perfect = have/has + past participle (“I have visited Rome”)। अब तक का अनुभव, वर्तमान परिणाम वाला हाल का काम, या अब तक जारी स्थिति के लिए प्रयोग करें (“She has worked here for three years”)। Yesterday/in 2020 जैसे समाप्त समय के साथ सामान्यतः past simple (“I visited Rome in 2020”)। Since + शुरुआत; for + अवधि। Been to = जाकर लौट चुका; gone to = अभी वहाँ है/रास्ते में है।',
          'Talk about three experiences, then give the exact time for one using past simple.'),
        lesson('g-int-perfect-continuous','Present perfect continuous','GRAMMAR','Emphasise duration or ongoing activity up to now.',
          'Form have/has been + verb-ing (“I have been studying”). Use it for an activity that started in the past and continues, or has just stopped with a visible result: “It has been raining all morning”; “You are tired—you have been running.” Focus is usually the activity/duration, not a finished quantity. With some state verbs (know, believe, own), use present perfect simple instead. Compare “I have read three chapters” (completed amount) with “I have been reading for two hours” (duration/activity).',
          'Have/has been + verb-ing बनाएँ (“I have been studying”)। अतीत में शुरू होकर अब तक जारी गतिविधि, या अभी-अभी रुकी और जिसका परिणाम दिख रहा हो, उसके लिए प्रयोग करें: “It has been raining all morning.” जोर सामान्यतः गतिविधि/अवधि पर है, पूरी हुई मात्रा पर नहीं। Know/believe/own जैसे state verb के साथ अक्सर present perfect simple आता है। तुलना: “I have read three chapters” = पूरी हुई मात्रा; “I have been reading for two hours” = अवधि/गतिविधि।',
          'Explain how long you have been learning something and what you have completed.'),
        lesson('g-int-past-aspects','Past continuous and past perfect','GRAMMAR','Set a scene and show which past event happened first.',
          'Past continuous = was/were + verb-ing; use it for a background action in progress at a past time or interrupted by another event (“I was cooking when she called”). Past simple gives the shorter event. Past perfect = had + past participle; use it to make an earlier past event clear (“The film had started before we arrived”). Do not use past perfect for every earlier event when the order is already clear; use it where the time relationship matters.',
          'Past continuous = was/were + verb-ing; बीते समय में जारी background action या जिसे दूसरी घटना ने रोका हो (“I was cooking when she called”)। छोटी घटना past simple में आती है। Past perfect = had + past participle; किसी दूसरी past घटना से पहले हुई घटना स्पष्ट करता है (“The film had started before we arrived”)। हर पुरानी घटना के लिए past perfect न लगाएँ; जब क्रम स्पष्ट करना ज़रूरी हो तभी प्रयोग करें।',
          'Describe what you were doing when something happened, then explain what had happened earlier.'),
        lesson('g-int-future-aspects','Future continuous and future perfect','GRAMMAR','Describe an action in progress or completed by a future time.',
          'Future continuous = will be + verb-ing (“At 8, I will be travelling”); it views an activity in progress at a future time and can make a question less direct (“Will you be using the car?”). Future perfect = will have + past participle (“By Friday, I will have finished”); it looks back from a future point at a completed action. Use by + time for the deadline. Future perfect continuous (will have been + -ing) emphasises duration up to a future point (“By June, I will have been working here for a year”).',
          'Future continuous = will be + verb-ing (“At 8, I will be travelling”); भविष्य के समय पर जारी गतिविधि दिखाता है, और प्रश्न को नरम कर सकता है (“Will you be using the car?”)। Future perfect = will have + past participle (“By Friday, I will have finished”); भविष्य के बिंदु से पीछे देखकर पूरी हो चुकी क्रिया बताता है। समय-सीमा के लिए by लगाएँ। Future perfect continuous अवधि पर जोर देता है: “By June, I will have been working here for a year.”',
          'Say what you will be doing tomorrow evening and what you will have finished by next week.'),
        lesson('g-int-tense-contrast','Choosing tense by meaning in conversation','GRAMMAR','Keep a story timeline clear when switching between tenses.',
          'Choose tense by the time viewpoint, not by translating a Hindi verb ending word for word. Present simple = routine/fact; continuous = in progress/temporary; past simple = finished past; present perfect = past linked to now; past continuous = past background; past perfect = earlier past; will/going to/present continuous = different future intentions/arrangements. Time markers help but do not decide by themselves (“today” can be unfinished or finished). Keep the same viewpoint across connected clauses unless the time meaning changes.',
          'Hindi के verb-ending का शब्दशः अनुवाद करने के बजाय समय के दृष्टिकोण से tense चुनें। Present simple = आदत/तथ्य; continuous = जारी/अस्थायी; past simple = समाप्त अतीत; present perfect = वर्तमान से जुड़ा अतीत; past continuous = अतीत की पृष्ठभूमि; past perfect = उससे पहले का अतीत; will/going to/present continuous = अलग भविष्य-इरादे/व्यवस्थाएँ। Time marker मदद करते हैं, पर अकेले निर्णय नहीं करते (“today” जारी भी हो सकता है, खत्म भी)। जुड़े विचारों में viewpoint तभी बदलें जब समय का अर्थ बदले।',
          'Tell a three-part story: background, main event and what had happened before it.'),
        lesson('g-int-conditionals','Conditionals: zero, first, second and third','GRAMMAR','Talk about facts, possible futures, imagined present and alternative pasts.',
          'Zero: if + present, present for general facts (“If water reaches 100°C, it boils”). First: if + present, will/can/may + base verb for a real future possibility (“If it rains, we will stay in”). Second: if + past, would + base verb for an unreal/less likely present or future (“If I had time, I would travel”). Third: if + past perfect, would have + past participle for an unreal past (“If we had left earlier, we would have caught it”). Usually do not put will/would in the if-clause.',
          'Zero: if + present, present = सामान्य तथ्य (“If water reaches 100°C, it boils”)। First: if + present, will/can/may + base verb = वास्तविक भविष्य संभावना। Second: if + past, would + base verb = काल्पनिक/कम संभावित वर्तमान या भविष्य। Third: if + past perfect, would have + past participle = बदला न जा सकने वाला काल्पनिक अतीत। सामान्यतः if-clause में will/would न रखें।',
          'Give one general fact, one real plan, one imagined wish and one past regret.'),
        lesson('g-int-passive','Passive voice across common tenses','GRAMMAR','Focus on a result or receiver when the doer is unknown or unimportant.',
          'Form passive with the correct tense of be + past participle: present “is made”; past “was made”; present perfect “has been made”; modal “must be made.” The object of the active sentence becomes the passive subject (“They repaired the road” → “The road was repaired”). Add by + agent only when useful (“by the council”). Use passive when the process/result matters, the actor is unknown, or a neutral/formal tone is needed. Do not use passive with verbs that have no object.',
          'Passive = tense के अनुसार be + past participle: present “is made”; past “was made”; present perfect “has been made”; modal “must be made.” Active sentence का object passive subject बनता है (“They repaired the road” → “The road was repaired”)। By + agent तभी जोड़ें जब उपयोगी हो। प्रक्रिया/नतीजा महत्वपूर्ण हो, करने वाला अज्ञात हो, या neutral/formal tone चाहिए तो passive उपयुक्त है। जिन verbs का object नहीं होता, उनका passive न बनाएँ।',
          'Explain how a familiar product is made, first with active and then passive sentences.'),
        lesson('g-int-reported-speech','Reported statements and questions','GRAMMAR','Report what someone said without repeating the exact words.',
          'Direct speech quotes the words; reported speech gives their meaning (“I am busy” → She said (that) she was busy). After a past reporting verb, backshift is common: present → past, past → past perfect, will → would; pronouns and time/place words change if the viewpoint changes. Backshift is optional when a fact is still true or the reporting verb is present. Report questions with ask + if/whether for yes/no or a question word for wh-questions, then statement word order (“He asked where I lived”), no question mark inside the reported clause.',
          'Direct speech में exact शब्द; reported speech में आशय (“I am busy” → She said she was busy)। Past reporting verb के बाद अक्सर tense पीछे जाता है: present → past, past → past perfect, will → would; viewpoint बदले तो pronoun/time/place भी बदलें। तथ्य अब भी सही हो या reporting verb present हो तो backshift वैकल्पिक है। Yes/no प्रश्न में ask + if/whether; wh-question में question word लगाएँ और statement क्रम रखें (“He asked where I lived”)। Reported clause में question mark न लगाएँ।',
          'Report a friend’s statement, a yes/no question and a wh-question.'),
        lesson('g-int-relative-clauses','Defining and non-defining relative clauses','GRAMMAR','Add identifying or extra information about a noun.',
          'Use who for people, which for things, that for people/things in defining clauses, and whose for possession. A defining clause identifies which person/thing and has no commas (“The book that you lent me is excellent”). A non-defining clause adds extra information, uses commas, and normally uses who/which—not that (“My brother, who lives in Pune, is visiting”). A relative pronoun can be omitted when it is the object in a defining clause (“the film (that) we watched”), but not when it is the subject (“the person who called”).',
          'People के लिए who, चीज़ों के लिए which, defining clause में people/things के लिए that, और अधिकार के लिए whose। Defining clause पहचान बताता है, comma नहीं (“The book that you lent me…”)। Non-defining clause अतिरिक्त जानकारी देता है, comma के बीच आता है और सामान्यतः that नहीं लेता (“My brother, who lives in Pune, …”)। Defining clause में object relative pronoun छोड़ा जा सकता है (“the film (that) we watched”), subject हो तो नहीं (“the person who called”)।',
          'Describe a person and a place using one defining and one extra-information clause.'),
        lesson('g-int-gerunds-infinitives','Gerunds and infinitives after verbs and prepositions','GRAMMAR','Choose -ing or to + verb based on the word pattern and meaning.',
          'A gerund is verb-ing used like a noun (“Swimming helps me relax”). Use -ing after prepositions (“interested in learning”), and after verbs such as enjoy, avoid, suggest. Use to + base verb after verbs such as want, decide, hope, plan. Some verbs allow both with little change (“start to rain/starting to rain”); some change meaning: stop doing = end an activity, stop to do = pause in order to do it; remember doing = recall a past action, remember to do = not forget a duty. Learn common verb patterns with the verb.',
          'Gerund = verb-ing का noun जैसा प्रयोग (“Swimming helps me relax”)। Preposition के बाद -ing (“interested in learning”), और enjoy/avoid/suggest जैसे verbs के बाद भी -ing। Want/decide/hope/plan के बाद to + base verb। कुछ verbs दोनों रूप लेते हैं, अर्थ लगभग समान; कुछ में अर्थ बदलता है: stop doing = गतिविधि रोकना; stop to do = कोई काम करने के लिए रुकना। remember doing = पुरानी घटना याद होना; remember to do = काम करना न भूलना। आम verb patterns साथ में याद करें।',
          'Talk about something you enjoy doing, plan to do and stopped doing.'),
        lesson('g-int-modals-meaning','Modals for obligation, permission, possibility and deduction','GRAMMAR','Choose a modal to show how certain, necessary or polite you are.',
          'Must/have to express strong obligation; must not prohibits; do not have to means unnecessary. Should/ought to give advice or expectation. May/might/could express possibility, with might often sounding less certain. Can/could/may ask permission; could/would you make requests more polite. For deductions, must be means strong positive conclusion, cannot be strong negative, and may/might/could be possible. Past deduction uses modal + have + participle (“She must have left”). Modals take a base verb; most have no -s and no do-support.',
          'Must/have to = मज़बूत बाध्यता; must not = मनाही; do not have to = ज़रूरत नहीं। Should/ought to = सलाह/अपेक्षा। May/might/could = संभावना; might अक्सर कम निश्चित। Can/could/may अनुमति पूछते हैं; could/would you request को विनम्र बनाते हैं। निष्कर्ष: must be = मजबूत सकारात्मक अनुमान; cannot be = मजबूत नकारात्मक; may/might/could be = संभव। Past अनुमान में modal + have + participle (“She must have left”)। Modal के बाद base verb; सामान्यतः -s या do-support नहीं।',
          'Explain three rules at work and make two guesses about what may have happened.'),
        lesson('g-int-quantifiers','Quantifiers, articles and reference','GRAMMAR','Make quantity and known/unknown reference precise.',
          'Use each/every with singular countable nouns; each views members individually, every views all members as a group. Both/either/neither refer to two; neither is negative (“Neither option works”). Few/little suggest not enough; a few/a little suggest some. Several/a number of take plural verbs; the amount of takes a singular verb with an uncountable noun. Use the when the listener can identify the reference, a/an for a new singular countable item, and no article for general plural/uncountable meanings. Some/any and much/many follow countability and sentence type.',
          'Each/every singular countable noun लेते हैं; each हर सदस्य अलग, every पूरी शृंखला पर दृष्टि देता है। Both/either/neither दो विकल्पों के लिए; neither नकारात्मक है। Few/little = अपर्याप्त; a few/a little = कुछ मात्रा। Several/a number of के साथ plural verb; the amount of + uncountable noun के साथ singular verb। सुनने वाला पहचान सके तो the; नया singular countable noun हो तो a/an; सामान्य plural/uncountable अर्थ में article नहीं। Some/any और much/many का चुनाव countability तथा वाक्य के प्रकार से करें।',
          'Describe two options and a group using each, neither, a few and the amount of.'),
        lesson('g-int-question-forms','Indirect questions, question tags and embedded questions','SPEAKING','Ask for information with a natural level of directness.',
          'Direct questions invert auxiliary and subject (“Where is the station?”). Embedded/indirect questions use statement word order after an opening (“Could you tell me where the station is?”), and do not use do-support in the embedded part. Use if/whether for indirect yes/no questions. Question tags generally use an auxiliary opposite to the statement (“You live nearby, don’t you?”); positive statement + negative tag is common. Intonation can rise when genuinely checking and fall when expecting agreement. Avoid tags with imperatives unless using a conventional form (“Have a seat, will you?”).',
          'Direct question में auxiliary और subject उलटते हैं (“Where is the station?”)। Indirect/embedded question में opening के बाद statement क्रम रखें (“Could you tell me where the station is?”); भीतर वाले हिस्से में do-support नहीं। Indirect yes/no प्रश्न के लिए if/whether। Question tag में कथन के उलट auxiliary आता है (“You live nearby, don’t you?”)। सच में पुष्टि चाहिए तो आवाज़ ऊपर; सहमति अपेक्षित हो तो नीचे जा सकती है। आदेश के साथ tag केवल प्रचलित रूप में रखें (“Have a seat, will you?”)।',
          'Ask for a location indirectly and check one belief with a question tag.'),
        lesson('g-int-clause-linking','Complex sentences: reason, contrast, purpose and result','GRAMMAR','Connect clauses without losing the relationship between ideas.',
          'Because/as/since introduce a reason clause; although/even though introduce contrast; so that introduces purpose; so/such…that show result. While/whereas can contrast or mark simultaneous time. A subordinate clause can come first with a comma (“Although it was late, we continued”) or after the main clause without a comma in many short cases. Do not use although and but together for one contrast. Avoid sentence fragments: a subordinate clause normally needs a main clause.',
          'Because/as/since कारण वाला clause; although/even though विरोध; so that उद्देश्य; so/such…that परिणाम बताते हैं। While/whereas विरोध या एक साथ घट रही क्रिया दिखा सकते हैं। Subordinate clause पहले आए तो comma लगाएँ (“Although it was late, we continued”); बाद में हो तो छोटे वाक्य में अक्सर comma नहीं। एक ही विरोध के लिए although और but साथ न लगाएँ। केवल subordinate clause लिखकर वाक्य अधूरा न छोड़ें—मुख्य clause जोड़ें।',
          'Explain a difficult choice using a reason, contrast and result clause.'),
        lesson('g-int-phrasal-verbs','Phrasal verbs and verb + preposition patterns','VOCABULARY','Understand multiword verbs and place their objects correctly.',
          'A phrasal verb combines a verb and particle (“find out”, “turn down”); a prepositional verb takes a fixed preposition (“depend on”, “look at”). Some are separable: “turn the offer down” / “turn down the offer”; with a pronoun, put it between verb and particle (“turn it down”). Some are inseparable (“look after the child”; not “look the child after”). Meaning can be literal or idiomatic. Learn the whole phrase, meaning, object pattern and an example together.',
          'Phrasal verb में verb + particle (“find out”, “turn down”); prepositional verb में निश्चित preposition (“depend on”, “look at”) आता है। Separable phrase में object बीच या बाद में: “turn the offer down/turn down the offer”; pronoun हमेशा बीच में (“turn it down”)। Inseparable में क्रम नहीं बदलता (“look after the child”; “look the child after” गलत)। अर्थ literal या मुहावरेदार हो सकता है। पूरा phrase, अर्थ, object का क्रम और उदाहरण साथ सीखें।',
          'Describe a recent task using find out, carry on and look after.'),
        lesson('g-int-discourse-markers','Discourse markers and spoken connectors','SPEAKING','Organise turns, add detail, soften a point and signal contrast.',
          'Use well/so to start or redirect a turn; actually/in fact to clarify or correct; anyway to return to a topic; by the way to introduce a side topic; I mean to reformulate; you know to appeal to shared knowledge. For structured contrast use however/on the other hand; for result use therefore/as a result. These markers are not interchangeable filler: choose one for its function and pause around it. In formal writing, avoid piling conversational markers together.',
          'Well/so से turn शुरू या दिशा बदलें; actually/in fact से स्पष्ट/सुधारें; anyway से विषय पर लौटें; by the way से अलग बात शुरू करें; I mean से दोबारा स्पष्ट करें; you know से साझा जानकारी का संकेत दें। व्यवस्थित विरोध के लिए however/on the other hand; परिणाम के लिए therefore/as a result। ये बिना अर्थ के filler नहीं—उद्देश्य के अनुसार चुनें और इनके आसपास pause लें। Formal writing में कई conversational marker एक साथ न भरें।',
          'Tell a story and use one marker to clarify, one to contrast and one to return to your point.'),
        lesson('g-int-comparative-structures','Advanced comparison and degree','GRAMMAR','Compare changing amounts and parallel qualities.',
          'Use as + adjective/adverb + as for equality (“as clear as”), not as/so…as mainly in negatives (“not as clear as”). Use less/fewer than for a smaller degree/number; the least/fewest for the lowest degree/number. “The more…, the more…” links proportional change (“The more you practise, the easier it gets”). Use far/much/a little before a comparative for degree (“much better”), not very better. Compare like with like: “The cost of A is lower than the cost of B.”',
          'बराबरी में as + adjective/adverb + as (“as clear as”); नकार में not as/so…as आम है। कम degree/संख्या के लिए less/fewer than; सबसे कम के लिए the least/fewest। “The more…, the more…” अनुपाती बदलाव जोड़ता है। Comparative से पहले far/much/a little degree बताते हैं (“much better”); very better नहीं। समान चीज़ों की तुलना करें: “The cost of A is lower than the cost of B.”',
          'Compare two ways of learning using equality, a comparative and a proportional pattern.'),
        lesson('g-int-question-intonation','Natural questions: word order, tags and intonation','SPEAKING','Combine accurate question grammar with conversational delivery.',
          'Wh-questions usually fall at the end when requesting information (“Where do you live?”); yes/no questions often rise when genuinely asking (“Are you ready?”), though intonation varies by context and accent. Keep the auxiliary before the subject in direct questions; keep statement order in indirect questions. Question tags invite confirmation; a rising tag signals uncertainty and a falling tag confidence. Use a friendly pace and stress the key information word rather than every word.',
          'जानकारी वाले wh-question में अंत पर आवाज़ सामान्यतः गिरती है; सच में पूछे yes/no question में अक्सर उठती है—लेकिन लहजा/परिस्थिति से बदलता है। Direct question में auxiliary subject से पहले; indirect question में statement क्रम। Question tag पुष्टि माँगता है; उठता tag अनिश्चितता, गिरता tag भरोसा जता सकता है। सहज गति रखें और मुख्य सूचना वाले शब्द पर जोर दें, हर शब्द पर नहीं।',
          'Ask a direct question, an indirect request for information and a confirmation tag aloud.'),
        lesson('g-int-getting-agreement','Suggestions, offers, agreement and disagreement','SPEAKING','Use grammar patterns that keep a conversation constructive.',
          'Suggestions: “Shall we…?”, “Why don’t we…?”, “We could…”. Offers: “Would you like me to…?” or “I can…”. Agreement: “That makes sense”; partial agreement: “I see your point, but…”. Disagreement can be softened with “I’m not sure I agree” or “Could we also consider…?”. After suggest, use a noun/gerund or that-clause (“I suggest taking a break”; “I suggest that we take a break”), not normally an infinitive (“suggest to take”).',
          'Suggestion: “Shall we…?”, “Why don’t we…?”, “We could…”。 Offer: “Would you like me to…?” या “I can…”。 सहमति: “That makes sense”; आंशिक सहमति: “I see your point, but…”। असहमति नरम करें: “I’m not sure I agree” या “Could we also consider…?” Suggest के बाद noun/gerund या that-clause (“I suggest taking a break”; “I suggest that we take a break”)—आम तौर पर infinitive नहीं (“suggest to take” नहीं)।',
          'Suggest a plan, accept one part and politely disagree with another part.'),
        lesson('g-int-used-to-patterns','Used to, be used to and get used to','GRAMMAR','Separate past habits from familiarity and the process of adapting.',
          'Used to + base verb describes a past state or repeated habit that is no longer true (“I used to live by the sea”). Negative/question forms are usually didn’t use to / Did you use to…? Be used to + noun or verb-ing means familiar/accustomed (“I am used to waking early”). Get used to + noun/-ing means become accustomed over time (“She is getting used to her new role”). Do not put a base verb after the preposition to in be/get used to.',
          'Used to + base verb = पुरानी आदत/स्थिति जो अब सच नहीं (“I used to live by the sea”)। नकार/प्रश्न: didn’t use to / Did you use to…? Be used to + noun/verb-ing = अभ्यस्त होना (“I am used to waking early”)। Get used to + noun/-ing = धीरे-धीरे अभ्यस्त होना (“She is getting used to her new role”)। Be/get used to में to preposition है, इसलिए उसके बाद base verb नहीं, noun या -ing आएगा।',
          'Compare a habit you used to have with something you are getting used to now.'),
        lesson('g-int-past-habits','Past habits: used to, would and past simple','GRAMMAR','Choose how to describe repeated actions and past states.',
          'Used to describes repeated past actions and past states no longer true (“We used to visit every summer”; “I used to be shy”). Would can describe repeated past actions in a narrative once a past time frame is established (“Every summer, we would visit…”), but it normally does not describe states (“not: would be shy”). Past simple can describe a repeated action when the time context is clear (“We visited every summer”). Used to makes the contrast with now more explicit.',
          'Used to पुरानी दोहराई क्रिया और अब बदल चुकी अवस्था दोनों बताता है (“We used to visit”; “I used to be shy”)। Would पहले से स्थापित past संदर्भ में दोहराई क्रिया की कहानी कहता है, लेकिन सामान्यतः अवस्था नहीं (“would be shy” नहीं)। स्पष्ट समय-संदर्भ हो तो past simple भी आदत बता सकता है। Used to अतीत और अब के contrast को सबसे साफ़ दिखाता है।',
          'Describe two past routines and one past state, then say what changed.'),
        lesson('g-int-perfect-adverbs','Just, already, yet and still with present perfect','GRAMMAR','Place common time adverbs to show recent, completed or pending events.',
          'Just means a very short time ago and usually goes between have/has and the past participle (“I have just arrived”). Already says sooner than expected and commonly goes in the same position (“She has already called”). Yet is common at the end of questions and negatives about an expected event (“Have you finished yet?”; “I haven’t finished yet”). Still emphasises that a situation continues, usually before the auxiliary in negatives (“I still haven’t heard”), and can signal surprise. British English often uses present perfect for recent news; American English may use past simple in some of these contexts.',
          'Just = अभी-अभी; सामान्यतः have/has और participle के बीच (“I have just arrived”)। Already = अपेक्षा से पहले; अक्सर इसी जगह (“She has already called”)। Yet अपेक्षित काम के प्रश्न/नकार में वाक्य के अंत (“Have you finished yet?”; “I haven’t finished yet”)। Still जारी स्थिति पर जोर देता है; नकार में अक्सर auxiliary से पहले (“I still haven’t heard”)। हाल की घटना में British English present perfect अधिक रखती है; American English कुछ जगह past simple भी रखती है।',
          'Tell someone what you have just done, already finished, still need to do and have not done yet.'),
        lesson('g-int-stative-dynamic-verbs','Stative and dynamic verbs','GRAMMAR','Know which verbs describe a state and which describe an action.',
          'Dynamic verbs describe actions/processes and can use continuous forms (“She is running”). Stative verbs describe thoughts, feelings, possession, senses or relationships (“know”, “believe”, “own”, “belong”) and are not normally continuous for that meaning (“I know”, not usually “I am knowing”). Some verbs have both meanings: “I think it is useful” (opinion/state) vs “I am thinking about it” (considering/action); “She has a car” (possession) vs “She is having lunch” (activity). Meaning determines the form.',
          'Dynamic verb क्रिया/प्रक्रिया बताता है, इसलिए continuous हो सकता है (“She is running”)। Stative verb विचार, भावना, अधिकार, इंद्रिय या संबंध बताता है (“know”, “believe”, “own”, “belong”) और उस अर्थ में सामान्यतः continuous नहीं (“I know”)। कुछ verbs के दोनों अर्थ: “I think it is useful” = राय; “I am thinking about it” = विचार कर रहा हूँ; “She has a car” = अधिकार; “She is having lunch” = गतिविधि। अर्थ के अनुसार रूप चुनें।',
          'Use think, have, see and taste once as a state and once as an action where possible.'),
        lesson('g-int-past-ability','Past ability: could, was able to and managed to','GRAMMAR','Distinguish general ability from success on one occasion.',
          'Could describes general ability in the past (“At ten, he could swim”). For one completed successful event, was/were able to or managed to is often preferred (“Despite the fog, we were able to land”). Could not can describe failure on one occasion (“We could not open the door”). Managed to emphasises effort or difficulty. In negative past ability, could not works for both general inability and a specific failure; context clarifies.',
          'Could सामान्य past ability (“At ten, he could swim”)। किसी एक पूरे हुए सफल मौके के लिए was/were able to या managed to अधिक स्वाभाविक (“We were able to land”)। Could not किसी खास मौके की असफलता बता सकता है (“We could not open the door”)। Managed to प्रयास/कठिनाई पर जोर देता है। नकारात्मक could not सामान्य अक्षमता और खास असफलता दोनों बता सकता है; संदर्भ स्पष्ट करता है।',
          'Describe one skill you had as a child and one difficult thing you managed to do.'),
        lesson('g-int-future-certainty','Degrees of certainty about the future','GRAMMAR','Show whether a prediction is certain, likely or only possible.',
          'Will expresses a prediction or confident expectation; definitely/probably can adjust certainty (“will probably arrive”). Be likely/unlikely to + verb describes probability (“Prices are likely to rise”). May/might/could + base verb express possibility, often less certain than will. Be bound/sure to is strong expectation; be not likely to is a weaker negative prediction. Place adverbs such as probably after will but before the main verb (“will probably work”). These are estimates, not mathematical percentages.',
          'Will अनुमान/भरोसेमंद अपेक्षा; definitely/probably निश्चितता बदलते हैं (“will probably arrive”)। Be likely/unlikely to + verb संभावना बताता है। May/might/could + base verb कम निश्चित संभावना है। Be bound/sure to मजबूत अपेक्षा; be not likely to कमजोर नकारात्मक अनुमान। Probably जैसे adverb will के बाद और main verb से पहले (“will probably work”)। ये अनुमान हैं, निश्चित प्रतिशत नहीं।',
          'Make one confident prediction, one likely outcome and one uncertain possibility.'),
        lesson('g-int-gradable-adjectives','Gradable and non-gradable adjectives','GRAMMAR','Match intensifiers to the strength and type of adjective.',
          'Gradable adjectives describe degrees and combine with a bit, fairly, very, extremely (“fairly cold”). Non-gradable adjectives describe an absolute or extreme state and commonly take absolutely/completely (“absolutely freezing”, “completely full”), not normally very in careful standard usage. Some adjectives can be gradable in one meaning and absolute in another. Really can modify both types in informal speech. Avoid treating every adjective as having one fixed scale; context and register affect natural combinations.',
          'Gradable adjective में मात्रा के स्तर होते हैं; a bit/fairly/very/extremely लग सकते हैं (“fairly cold”)। Non-gradable adjective पूर्ण/अत्यधिक अवस्था बताता है; absolutely/completely आम हैं (“absolutely freezing”, “completely full”), सावधान standard usage में very कम। कुछ adjective अर्थ बदलने पर gradable या absolute हो सकते हैं। Informal बोलचाल में really दोनों के साथ आता है। Natural combination संदर्भ और register से बदलता है।',
          'Describe the weather using one gradable and one extreme adjective with a suitable intensifier.'),
        lesson('g-int-so-such-too-enough','So, such, too and enough','GRAMMAR','Intensify qualities and express excess or sufficiency.',
          'So + adjective/adverb (“so useful”); such + noun phrase (“such a useful book”; “such useful advice”). Too + adjective/adverb means more than wanted/needed (“too late”); too much/many go before nouns. Adjective/adverb + enough means sufficient (“old enough”), while enough + noun means a sufficient quantity (“enough time”). So/such…that can show a result (“It was so cold that…”). Place enough after an adjective but before a noun.',
          'So + adjective/adverb (“so useful”); such + noun phrase (“such a useful book”; “such useful advice”)। Too + adjective/adverb = ज़रूरत/इच्छा से अधिक (“too late”); too much/many noun से पहले। Adjective/adverb + enough = पर्याप्त (“old enough”); enough + noun = पर्याप्त मात्रा (“enough time”)। So/such…that परिणाम दिखाते हैं। Enough adjective के बाद लेकिन noun से पहले आता है।',
          'Explain why a plan is too expensive, then suggest a cheaper option that is good enough.'),
        lesson('g-int-as-like','As and like','GRAMMAR','Compare similarity and explain roles or functions.',
          'Like is a preposition meaning similar to and is followed by a noun/pronoun (“She sings like her mother”). As can be a conjunction followed by a clause (“Do as I asked”) or mean in the role/function of (“work as a guide”). As…as forms comparisons (“as quick as”). In informal speech, like is often used before a clause, but in careful formal English as/as if is preferred. Compare “like a teacher” (similar to one) with “as a teacher” (in that job/role).',
          'Like preposition है, अर्थ समानता; इसके बाद noun/pronoun (“She sings like her mother”)। As conjunction बनकर clause ले सकता है (“Do as I asked”) या भूमिका/काम (“work as a guide”)। As…as तुलना बनाता है। Informal speech में clause से पहले like आम है; सावधान formal English में as/as if पसंद किया जाता है। “like a teacher” = शिक्षक जैसा; “as a teacher” = शिक्षक की भूमिका में।',
          'Compare how you sound like someone and what you do as a learner or colleague.'),
        lesson('g-int-punctuation-capitals','Capital letters, apostrophes and punctuation in clear English','WRITING','Use written conventions that help spoken and written ideas stay clear.',
          'Capitalize the first word of a sentence, the pronoun I, names, languages, nationalities, days and months. Apostrophe + s can mark possession (“Rina’s bag”) or a contraction (“Rina’s here” = Rina is); plural possessives place the apostrophe after final s (“students’ work”). Its is possessive; it’s means it is/has. Use a full stop to close a statement, a question mark for a direct question, and commas to separate list items or introductory clauses where needed. Punctuation does not reproduce every pause in speech.',
          'वाक्य का पहला शब्द, pronoun I, नाम, language, nationality, दिन और महीने capital से शुरू करें। Apostrophe + s अधिकार (“Rina’s bag”) या contraction (“Rina’s here” = Rina is) दिखा सकता है; plural possessive में अंतिम s के बाद apostrophe (“students’ work”)। Its अधिकार; it’s = it is/has। कथन के अंत में full stop, direct question में question mark; सूची/कुछ introductory clause में comma। Punctuation बोलने के हर pause की नकल नहीं है।',
          'Write a short message with a name, a plural possessive, a contraction and a direct question.')
      ]
    },
    Advanced: {
      subtitle: 'C1 · express nuance, emphasis and precise relationships',
      lessons: [
        lesson('g-adv-mixed-conditionals','Mixed conditionals and implied conditions','GRAMMAR','Connect a past condition with a present result and vice versa.',
          'Mixed conditionals combine different time frames. Past condition → present result: if + past perfect, would + base (“If I had taken that job, I would live abroad now”). Present general condition → past result is less common and context-dependent (“If she were more organised, she would not have missed the deadline”). The if-clause can be replaced by inversion in formal style (“Had I known, I would have called”). Use these only when the imagined condition and real timeline are clear.',
          'Mixed conditional अलग समय-सीमा जोड़ता है। अतीत की शर्त → वर्तमान परिणाम: if + past perfect, would + base (“If I had taken that job, I would live abroad now”)। वर्तमान सामान्य गुण → अतीत का परिणाम कम आम है और संदर्भ माँगता है। Formal शैली में if हटाकर inversion कर सकते हैं (“Had I known, I would have called”)। काल्पनिक शर्त और वास्तविक समय-रेखा स्पष्ट हो तभी प्रयोग करें।',
          'Explain how one past decision affects your life now using a mixed conditional.'),
        lesson('g-adv-wish-subjunctive','Wish, if only, would rather and the subjunctive','GRAMMAR','Express regret, preference, urgency and formal recommendations.',
          'Wish/if only + past simple describes a present situation you want different (“I wish I knew”); + past perfect expresses past regret (“I wish I had called”); + would often complains about another person’s repeated behaviour or a desired change (“I wish it would stop”). Would rather + subject + past form expresses a preference about someone else (“I’d rather you came earlier”). In formal mandative clauses, suggest/insist/recommend + that + subject + base verb is possible (“They recommended that he be present”); British usage may also use should.',
          'Wish/if only + past simple = वर्तमान की ऐसी स्थिति जो बदलनी हो (“I wish I knew”); + past perfect = अतीत का पछतावा (“I wish I had called”); + would = दूसरे के बार-बार व्यवहार पर शिकायत/बदलाव की इच्छा। Would rather + subject + past = दूसरे के बारे में पसंद (“I’d rather you came earlier”)। Formal mandative clause में suggest/insist/recommend + that + subject + base verb (“They recommended that he be present”); British English में should भी संभव है।',
          'Say one present wish, one past regret and one formal recommendation.'),
        lesson('g-adv-inversion-emphasis','Inversion after negative and limiting expressions','GRAMMAR','Use auxiliary inversion for emphasis and formal effect.',
          'After fronted negative/limiting expressions, put an auxiliary before the subject: “Never have I seen…”, “Rarely does she complain”, “Not until Friday did we know.” If there is no auxiliary, use do/does/did + base verb. “Not only” also triggers inversion in its fronted clause (“Not only did he apologise, but he also fixed it”). Inversion is formal/emphatic; ordinary subject–verb order is safer in everyday conversation. Do not invert after every negative word when it stays in normal position (“I have never seen it”).',
          'वाक्य के शुरू में negative/limiting expression लाने पर auxiliary subject से पहले रखें: “Never have I seen…”, “Rarely does she complain”, “Not until Friday did we know.” Auxiliary न हो तो do/does/did + base verb लगाएँ। शुरू में Not only भी inversion लेता है। यह formal/emphatic शैली है; रोज़मर्रा की बातचीत में सामान्य subject–verb क्रम सुरक्षित है। जब never अपनी सामान्य जगह पर हो तो inversion नहीं (“I have never seen it”)।',
          'Emphasise a surprising experience and a delayed decision using fronted expressions.'),
        lesson('g-adv-cleft-sentences','Cleft sentences and focus','GRAMMAR','Emphasise the person, time, reason or action that matters.',
          'It-cleft: It + be + focus + that/who-clause (“It was Maya who found the error”). Wh-cleft: What + clause + be + focus (“What we need is more time”). Use clefts to correct a misunderstanding, contrast alternatives or guide attention. Keep the relative clause grammatical and avoid using cleft structures in every sentence; overuse sounds heavy. Stress the focused element in speech.',
          'It-cleft: It + be + जोर वाला भाग + that/who-clause (“It was Maya who found the error”)। Wh-cleft: What + clause + be + जोर वाला भाग (“What we need is more time”)। गलतफ़हमी सुधारने, विकल्पों में contrast या ध्यान निर्देशित करने के लिए प्रयोग करें। Relative clause का grammar सही रखें; हर वाक्य cleft न बनाएँ—अति से भाषा भारी लगती है। बोलते समय मुख्य focused भाग पर जोर दें।',
          'Correct a misunderstanding by emphasising who acted and what outcome is needed.'),
        lesson('g-adv-ellipsis-substitution','Ellipsis and substitution in natural conversation','GRAMMAR','Avoid repeating information while keeping the meaning recoverable.',
          'Ellipsis leaves out words that context makes clear (“Want some?” = Do you want some?). Substitute with so/not after verbs such as think, hope, suppose (“I think so”; “I hope not”), with do so to replace an action, and one/ones to replace a countable noun (“the red one”). Auxiliary ellipsis is common in short responses (“I can, but she can’t”). Use ellipsis only when the listener can recover the missing material; in formal writing, ensure the reference is unambiguous.',
          'संदर्भ से स्पष्ट शब्द छोड़े जा सकते हैं (“Want some?” = Do you want some?)। Think/hope/suppose के बाद so/not (“I think so”; “I hope not”), do so किसी action को, one/ones countable noun को बदलते हैं (“the red one”)। छोटे उत्तर में auxiliary अकेला रह सकता है (“I can, but she can’t”)। शब्द तभी छोड़ें जब सुनने वाला अर्थ समझ सके; formal writing में reference अस्पष्ट न हो।',
          'Answer naturally without repeating the full question, using so, not or one.'),
        lesson('g-adv-participles','Participle clauses and reduced relative clauses','GRAMMAR','Compress clauses when the subject relationship is clear.',
          'An -ing participle clause can show a simultaneous action or reason (“Walking home, I called her”); a past participle clause often has passive meaning (“Built in 1900, the bridge…”). A perfect participle having + past participle marks an earlier completed action (“Having checked the figures, she sent the report”). The understood subject must normally match the main-clause subject to avoid a dangling modifier. Reduced relatives omit a relative pronoun and be (“the people waiting outside”; “the files sent yesterday”).',
          '-ing participle clause साथ चल रही क्रिया/कारण दिखा सकती है; past participle clause अक्सर passive अर्थ (“Built in 1900, the bridge…”)। Having + past participle पहले पूरी हुई क्रिया (“Having checked the figures, she sent the report”)। छोड़े गए clause का subject सामान्यतः मुख्य clause के subject से मेल खाना चाहिए, वरना dangling modifier होगा। Reduced relative में relative pronoun और be छूट सकता है (“the people waiting outside”; “the files sent yesterday”)।',
          'Shorten a two-sentence process description with one correctly matched participle clause.'),
        lesson('g-adv-causative','Causative have/get and make/let/help','GRAMMAR','Say who arranges, requires or permits another person to act.',
          'Have/get something done means arrange for a service (“I had my laptop repaired”; “I got it fixed”). Have + person + base verb gives an instruction/arrangement (“I had the technician check it”); get + person + to-infinitive means persuade/arrange (“I got him to check it”). Make + object + base verb means compel; let + object + base verb means permit; help can take a base verb or to-infinitive. In passive, make takes to (“He was made to wait”).',
          'Have/get something done = किसी सेवा का प्रबंध (“I had my laptop repaired”; “I got it fixed”)। Have + person + base verb = निर्देश/व्यवस्था; get + person + to-infinitive = मनाना/व्यवस्था। Make + object + base verb = मजबूर करना; let + object + base verb = अनुमति; help के बाद base verb या to-infinitive। Passive में make के बाद to आता है (“He was made to wait”)।',
          'Explain how you arranged a repair, persuaded someone to help and let a colleague choose.'),
        lesson('g-adv-passive-reporting','Reporting passives and impersonal reporting structures','GRAMMAR','Report claims when the source is broad, unknown or less important.',
          'Two common forms: “It is said/believed/reported that…” and “She is said/believed/reported to…” (“It is believed that the painting is genuine”; “The painting is believed to be genuine”). Use to have + past participle for an earlier event (“He is reported to have left”). These forms distance the speaker from a claim and are common in news/formal speech. Do not present an allegation as verified fact; keep the reporting verb to show its status.',
          'दो रूप: “It is said/believed/reported that…” और “She is said/believed/reported to…”। पहले हुई घटना के लिए to have + past participle (“He is reported to have left”)। समाचार/formal भाषा में जब स्रोत व्यापक/अज्ञात या कम महत्वपूर्ण हो, तब प्रयोग करें; इससे वक्ता दावा आगे रखता है, पुष्टि नहीं करता। आरोप को पक्का तथ्य न बनाएँ—reporting verb उसकी स्थिति स्पष्ट रखता है।',
          'Report an unconfirmed claim carefully, then report a completed event with to have.'),
        lesson('g-adv-hedging','Hedging, stance and degrees of certainty','SPEAKING','Express careful confidence without making your message vague.',
          'Hedges limit how strongly a statement is made: may/might, seems/appears, tends to, probably, to some extent, as far as we know. Use evidence markers (“Based on the figures…”) and scope (“In most cases…”) to be precise. Could/would can soften requests and proposals. A hedge should match real uncertainty; stacking several (“perhaps it might possibly…”) weakens clarity. State the main point first, then qualify the uncertain part.',
          'Hedge दावे की निश्चितता सीमित करता है: may/might, seems/appears, tends to, probably, to some extent, as far as we know। Evidence (“Based on the figures…”) और सीमा (“In most cases…”) बताकर सटीक रहें। Could/would request/proposal नरम कर सकते हैं। Hedge वास्तविक अनिश्चितता से मेल खाना चाहिए; कई hedge जोड़ने से संदेश धुंधला होता है। मुख्य बात पहले कहें, फिर अनिश्चित हिस्से को qualify करें।',
          'Give a recommendation with one piece of evidence and one appropriately cautious qualification.'),
        lesson('g-adv-fronting-dislocation','Fronting, topicalisation and afterthoughts','GRAMMAR','Move information to manage focus and shared context in speech.',
          'Fronting places a familiar or contrastive element first (“That part, I can explain”). Left dislocation adds a pronoun to resume the topic (“My sister, she works in Delhi”); it is conversational and not usually formal writing. Right dislocation adds an afterthought (“She is very patient, my manager”). These patterns help organise spoken information but can sound marked or regional. Use standard subject–verb–object order when clarity or formality matters.',
          'Fronting में परिचित/contrast वाला भाग पहले आता है (“That part, I can explain”)। Left dislocation में topic के बाद pronoun दोबारा आता है (“My sister, she works in Delhi”); यह बातचीत में आम, formal writing में कम। Right dislocation बाद में अतिरिक्त जानकारी जोड़ता है। ये spoken information व्यवस्थित करते हैं पर marked/regional लग सकते हैं। स्पष्टता/formality चाहिए तो सामान्य SVO क्रम रखें।',
          'Give a conversational answer that puts the contrastive topic first, then restate it clearly.'),
        lesson('g-adv-nominalisation','Noun clauses and nominalisation','GRAMMAR','Package ideas as noun phrases while keeping speech understandable.',
          'A noun clause can function as subject/object: that-clause (“I believe that the plan will work”), wh-clause (“What she decided surprised us”), or whether/if clause (“We do not know whether it is ready”). Nominalisation turns verbs/adjectives into nouns (“decide → decision”, “efficient → efficiency”). It can make formal speech concise but often hides the actor and creates long, abstract sentences. In speaking, prefer a clear verb when it makes responsibility easier to understand.',
          'Noun clause subject/object बन सकता है: that-clause, wh-clause, whether/if-clause (“We do not know whether it is ready”)। Nominalisation verb/adjective को noun बनाता है (“decide → decision”, “efficient → efficiency”)। Formal speech में संक्षिप्तता मिल सकती है, पर actor छिप सकता है और वाक्य अमूर्त/लंबा हो सकता है। बोलते समय स्पष्ट verb चुनें जहाँ उससे ज़िम्मेदारी समझना आसान हो।',
          'Explain a decision once with a noun clause and once with a direct verb.'),
        lesson('g-adv-modality-past','Modal meanings in the past','GRAMMAR','Distinguish past ability, missed possibility, criticism and deduction.',
          'Could often describes general past ability (“I could read at four”), while was/were able to or managed to often describes one successful occasion. Could not / was not able to describe failure. Could have + participle can mean a past possibility or an unrealised option (“We could have taken a taxi”). Should have + participle criticises/regrets a past action; need not have means it was unnecessary but happened. Must have/might have/cannot have express strong, possible or negative deduction about the past.',
          'Could सामान्य past ability (“I could read at four”); एक विशेष मौके की सफल क्षमता के लिए was/were able to या managed to भी आम। असफलता: could not/was not able to। Could have + participle = past संभावना या न किया गया विकल्प। Should have + participle = पिछली गलती पर आलोचना/पछतावा; need not have = ज़रूरत नहीं थी, फिर भी किया। Must/might/cannot have + participle = अतीत पर मजबूत/संभावित/नकारात्मक अनुमान।',
          'Reflect on a missed opportunity and distinguish what was possible from what should have happened.'),
        lesson('g-adv-future-in-past','Future in the past and backshifted plans','GRAMMAR','Describe plans and predictions from a past viewpoint.',
          'Was/were going to describes a past intention, often one that changed (“I was going to call, but I forgot”). Would can report a future seen from the past (“She said she would return”) or describe a repeated past habit in a narrative. Was/were to is formal for an arranged future event. Keep the viewpoint consistent in reported speech; will commonly backshifts to would after a past reporting verb, unless the future is still current and the speaker chooses not to backshift.',
          'Was/were going to = अतीत का इरादा, जो बदल भी गया हो (“I was going to call, but I forgot”)। Would अतीत के दृष्टिकोण से भविष्य (“She said she would return”) या कहानी की दोहराई आदत बता सकता है। Was/were to formal तय भविष्य घटना है। Reported speech में viewpoint सुसंगत रखें; past reporting verb के बाद will सामान्यतः would बनता है, पर भविष्य अब भी वर्तमान हो तो backshift वैकल्पिक है।',
          'Describe a plan you had, what changed and what someone promised to do.'),
        lesson('g-adv-advanced-connectors','Concession, contrast and argument structure','SPEAKING','Concede a point, qualify an argument and return to your conclusion.',
          'Although/even though + clause; despite/in spite of + noun or -ing (“Despite the cost…”). However/nevertheless connect contrasting clauses and are usually set off by punctuation. Whereas contrasts two facts; while can mean contrast or time. On the one hand…on the other hand… frames two sides. Concede with “Admittedly…” or “That said…” then state why your conclusion still follows. Avoid double marking (“Although…, but…”), and make each connector’s logical relation explicit.',
          'Although/even though + clause; despite/in spite of + noun या -ing (“Despite the cost…”)। However/nevertheless विरोधी clauses जोड़ते हैं और punctuation से अलग रखे जाते हैं। Whereas दो तथ्यों का contrast; while contrast या समय। On the one hand…on the other hand… दोनों पक्ष दिखाता है। “Admittedly…”/“That said…” से मान्यता देकर फिर निष्कर्ष का कारण दें। दोहरा connector (“Although…, but…”) न लगाएँ; संबंध स्पष्ट रखें।',
          'Make a balanced argument: concede one drawback, contrast it with a benefit and conclude.'),
        lesson('g-adv-register-spoken-grammar','Register, contractions and natural spoken grammar','SPEAKING','Choose forms that sound natural for the audience and setting.',
          'Contractions (I’m, we’ve, don’t) are normal in conversation and many informal messages; avoid them when a formal genre requires expansion. Spoken English uses short responses, ellipsis, discourse markers and informal phrasal verbs; formal presentations may use fuller clauses and precise vocabulary. Register depends on audience, relationship, purpose and channel—not a simple “correct/incorrect” scale. Avoid forcing slang or contractions into a serious formal context; keep grammar clear even when casual.',
          'बातचीत और informal संदेशों में contractions (I’m, we’ve, don’t), छोटे उत्तर, ellipsis, discourse marker और phrasal verb स्वाभाविक हैं; formal genre में पूरे रूप और स्पष्ट clauses बेहतर हो सकते हैं। Register श्रोता, रिश्ता, उद्देश्य और माध्यम पर निर्भर है—सिर्फ सही/गलत का पैमाना नहीं। गंभीर formal संदर्भ में slang न ठूँसें; casual tone में भी grammar स्पष्ट रखें।',
          'Say the same request to a friend and to a senior colleague, adjusting register without changing meaning.'),
        lesson('g-adv-word-order-focus','Word order, information focus and end-weight','GRAMMAR','Arrange old and new information so the listener can follow your point.',
          'Neutral English clauses usually follow subject–verb–object; place familiar information early and heavier/new information later when possible. End-weight puts a long phrase near the end (“We explained the new policy to everyone who joined this week”). Use inversion only for specific emphasis, questions or formal patterns. Adverbs have flexible but constrained positions: frequency adverbs usually before a main verb and after be; manner/place/time often follow the object. Unusual order can shift focus, so use it deliberately.',
          'सामान्य English clause का क्रम subject–verb–object है; परिचित जानकारी पहले और लंबी/नई जानकारी बाद में रखना listener को मदद देता है। End-weight में लंबा phrase अंत की ओर (“We explained the new policy to everyone who joined this week”)। Inversion केवल खास जोर, प्रश्न या formal pattern में। Adverb की जगह लचीली मगर नियमबद्ध है: frequency adverb main verb से पहले/be के बाद; manner/place/time अक्सर object के बाद। असामान्य क्रम focus बदलता है, इसलिए सोचकर प्रयोग करें।',
          'Rewrite a long sentence so the familiar point comes first and the new detail comes last.'),
        lesson('g-adv-collocation-prepositions','Dependent prepositions, collocations and precision','VOCABULARY','Choose natural word partnerships rather than translating word by word.',
          'Many adjectives, nouns and verbs select a particular preposition: interested in, responsible for, depend on, an increase in, discuss something (no preposition). Collocations also constrain word choice: make a decision, take responsibility, strong evidence. A dictionary gives possibilities, but learn the whole phrase in a sentence and note register. Do not assume the Hindi preposition maps directly to English; check the English pattern and its object/gerund form.',
          'कई adjective/noun/verb के साथ तय preposition आता है: interested in, responsible for, depend on, an increase in; discuss के बाद object सीधे आता है, preposition नहीं। Collocation शब्दों की स्वाभाविक जोड़ी है: make a decision, take responsibility, strong evidence। शब्दकोश संभावनाएँ देता है; पूरा phrase sentence और register सहित सीखें। Hindi postposition का सीधा English अनुवाद न मानें; English pattern और उसके object/gerund को देखें।',
          'Describe a work or study goal using three accurate collocations and their prepositions.'),
        lesson('g-adv-rhetorical-questions','Rhetorical questions, echo questions and repair','SPEAKING','Use questions to engage, confirm and repair understanding.',
          'A rhetorical question invites thought rather than an answer (“Who wouldn’t want that?”). Echo questions repeat all or part of a previous turn to show surprise or check hearing (“You moved where?”); rising intonation is common. Repair phrases include “Do you mean…?”, “So, if I understand correctly…”, and “Could you rephrase that?” These are interaction tools, not ordinary information questions. Use rhetorical questions sparingly in formal speech, and use a neutral clarification when accuracy matters.',
          'Rhetorical question उत्तर के बजाय सोचने को आमंत्रित करता है (“Who wouldn’t want that?”)। Echo question पिछले शब्द दोहराकर आश्चर्य/सुनने की पुष्टि करता है (“You moved where?”); उठता intonation आम है। Repair phrases: “Do you mean…?”, “So, if I understand correctly…”, “Could you rephrase that?” ये बातचीत संभालने के तरीके हैं, सामान्य जानकारी प्रश्न नहीं। Formal speech में rhetorical question सीमित रखें; सटीकता ज़रूरी हो तो साफ़ clarification करें।',
          'Practise confirming a detail, echoing a surprising fact and politely asking for a rephrase.'),
        lesson('g-adv-pronunciation-grammar','Stress, reductions and grammar in spoken rhythm','PRONUNCIATION','Make grammatical phrases easier to understand through stress and rhythm.',
          'Content words (main nouns, verbs, adjectives, adverbs) usually carry more stress; function words (articles, auxiliaries, prepositions) are often reduced in fluent speech. Contractions reflect common reductions (“I have” → “I’ve”; “do not” → “don’t”). Stress can change contrast (“I asked HER” vs “I ASKED her”). Keep the grammatical form intact even when sounds reduce; practise listening and repeating whole chunks. Accent differences are normal—aim for intelligibility, not one accent.',
          'Content words (मुख्य noun, verb, adjective, adverb) पर सामान्यतः अधिक stress; function words (article, auxiliary, preposition) fluent speech में अक्सर कमजोर होते हैं। Contractions आम reduction दिखाते हैं (“I have” → “I’ve”)। Stress से contrast बदलता है (“I asked HER” बनाम “I ASKED her”)। आवाज़ घटे तब भी grammatical form सही रखें; पूरे phrase सुनकर दोहराएँ। अलग accent सामान्य हैं—लक्ष्य समझ में आना है, एक खास accent की नकल नहीं।',
          'Say one sentence twice, stressing different words to show two different contrasts.')
      ]
    }
  };
})();
